import org.apache.kafka.clients.producer.*;
import java.util.Properties;

Properties props = new Properties();
props.put("bootstrap.servers", "kafka1:9092,kafka2:9092");
props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
props.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");
props.put("compression.type", "snappy"); // batch & compress
props.put("linger.ms", "20"); // wait to batch

Producer<String,String> producer = new KafkaProducer<>(props);
for (int i = 0; i < 1000; i++) {
  ProducerRecord<String,String> r = new ProducerRecord<>("activity-stream", Integer.toString(i%100), "event-" + i);
  producer.send(r, (metadata, ex) -> {
    if (ex != null) ex.printStackTrace();
    else System.out.println("sent to " + metadata.topic() + " partition " + metadata.partition());
  });
}
producer.flush();
producer.close();

