/* Additional concise Node.js example: append and replay */
const EventEmitter = require('events');
class InMemoryStore extends EventEmitter {
  constructor(){ super(); this.streams = new Map(); }
  async appendToStream(stream, event){
    if(!this.streams.has(stream)) this.streams.set(stream, []);
    this.streams.get(stream).push(event);
    this.emit('event', stream, event);
    return true;
  }
  async readStream(stream){
    return this.streams.get(stream) || [];
  }
}

// usage
(async ()=>{
  const store = new InMemoryStore();
  await store.appendToStream('order-1', { type: 'OrderPlaced', data: {id:'1'} });
  const events = await store.readStream('order-1');
  console.log('replay events:', events);
})();
